def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            main, build = v.rsplit('+', 1)
        else:
            main = v
            build = ''

        # Split off pre-release (everything after '-')
        if '-' in main:
            base, prerelease = main.split('-', 1)
        else:
            base = main
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(identifiers):
        # A version with a pre-release sorts before the same version without one
        # So we need to return a tuple where:
        # - No pre-release gets (1,) as prefix
        # - Pre-release gets (0, ...) as prefix
        if not identifiers:
            return (1,)

        key = [0]
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers compare numerically and sort before non-digit
                key.append((0, int(identifier)))
            else:
                # Other identifiers compare by ASCII order
                key.append((1, identifier))
        return tuple(key)

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        return (major, minor, patch, prerelease_sort_key(prerelease_identifiers))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

